message:
Interesting! The `skcms_A2B` struct is 656 bytes, not 320 as I calculated. The `skcms_Curve` struct must be larger than 24 bytes. Let me check:

<｜｜DSML｜｜=execute_bash>
<｜｜DSML｜｜=command>cd /workspace/repo-vul/src-vul/skcms && cat > /tmp/check_size2.c << 'EOF'
#include <stdio.h>
#include "skcms.h"
int main() {
    printf("sizeof(skcms_Curve) = %zu\n", sizeof(skcms_Curve));
    printf("sizeof(skcms_Matrix3x4) = %zu\n", sizeof(skcms_Matrix3x4));
    printf("offsetof(skcms_A2B, input_curves) = %zu\n", __builtin_offsetof(skcms_A2B, input_curves));
    printf("offsetof(skcms_A2B, matrix_channels) = %zu\n", __builtin_offsetof(skcms_A2B, matrix_channels));
    printf("offsetof(skcms_A2B, matrix_curves) = %zu\n", __builtin_offsetof(skcms_A2B, matrix_curves));
    printf("offsetof(skcms_A2B, matrix) = %zu\n", __builtin_offsetof(skcms_A2B, matrix));
    printf("offsetof(skcms_A2B, output_channels) = %zu\n", __builtin_offsetof(skcms_A2B, output_channels));
    printf("offsetof(skcms_A2B, output_curves) = %zu\n", __builtin_offsetof(skcms_A2B, output_curves));
    return 0;
}
EOF
gcc -I. -o /tmp/check_size2 /tmp/check_size2.c skcms.c -lm && /tmp/check_size2</｜｜DSML｜｜>
</｜｜DSML｜｜>

